WITH upsert AS
(
    UPDATE pay11_month_item
       SET pay11_month_id  = #{monthId},
           pay11_item_type = #{itemType},
           pay11_item_cd   = #{itemCode},
           pay11_item_amt  = #{itemAmt}
     WHERE pay11_month_item_id = #{monthItemId}
       AND pay11_month_id      = #{monthId}
 RETURNING *
)
INSERT INTO pay11_month_item
       (pay11_month_item_id, pay11_month_id, pay11_item_type, pay11_item_cd, pay11_item_amt)
SELECT f_create_seq(), #{monthId}, #{itemType}, #{itemCode}, #{itemAmt}
 WHERE NOT EXISTS ( SELECT * FROM upsert )

